import{_ as a,o as i,c as e,a8 as t}from"./chunks/framework.CNIpabDg.js";const c=JSON.parse('{"title":"Create a development package","description":"Build a development-only Xila archive with the shared native xila-package builder.","frontmatter":{"layout":"doc","docType":"how-to","description":"Build a development-only Xila archive with the shared native xila-package builder."},"headers":[],"relativePath":"how-to/package-application.md","filePath":"how-to/package-application.md","lastUpdated":1793045410000}'),n={name:"how-to/package-application.md"};function l(p,s,h,r,o,k){return i(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793045410000"},[...s[0]||(s[0]=[t(`<h1 id="create-a-development-package" tabindex="-1">Create a development package <a class="header-anchor" href="#create-a-development-package" aria-label="Permalink to &quot;Create a development package&quot;">​</a></h1><p>Use <a href="https://github.com/xila-project/package_manager" target="_blank" rel="noreferrer"><code>Xila-Project/package_manager</code></a>&#39;s native <code>xila-package</code> executable to produce an <strong>experimental development <code>.xpk</code> archive</strong>. This workflow packages files for inspection; it does <strong>not</strong> install applications in Xila or make a package trustworthy for execution.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Use a native development host with Git, Rust and <a href="https://mise.jdx.dev/" target="_blank" rel="noreferrer">mise</a> 2026.9.2 or newer. You need an already-built application payload, such as a <code>wasm32-wasip1</code> guest from <a href="/how-to/build-guest.html">Build a guest</a>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/xila-project/package_manager.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package_manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trust</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The repository pins Rust 1.99.0, integrates mr-boxington and runs its Cargo tasks through mise. Its host builder is in Cargo package <code>xila-package-builder</code>, but the compiled executable is named <strong><code>xila-package</code></strong>. Cargo crate names are prefixed with <code>xila-package-</code>; filesystem folder names are simply <code>crates/manifest</code>, <code>crates/reader</code> and so on.</p><h2 id="_1-stage-the-application-files" tabindex="-1">1. Stage the application files <a class="header-anchor" href="#_1-stage-the-application-files" aria-label="Permalink to &quot;1. Stage the application files&quot;">​</a></h2><p>From the <code>package_manager</code> repository root, prepare a folder containing <strong>only installable payload files</strong>, with no symlinks or special files:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app/bin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/calculator.wasm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app/bin/calculator.wasm</span></span></code></pre></div><p>The manifest file must live <strong>outside</strong> the source directory. The builder recursively scans files, rejects links/special entries, computes SHA-256 with a fixed 8 KiB input buffer and sorts paths deterministically.</p><h2 id="_2-generate-or-refresh-the-manifest" tabindex="-1">2. Generate or refresh the manifest <a class="header-anchor" href="#_2-generate-or-refresh-the-manifest" aria-label="Permalink to &quot;2. Generate or refresh the manifest&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-package-builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./manifest.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila.calculator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wasm32-wasip1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>The arguments after <code>manifest generate</code> are, in order: source directory, output JSON manifest, dotted package identifier, version, target triple and minimum Xila ABI version. Check the generated JSON and the requested capability list before sharing it. The current format has no finalized permission policy.</p><p>When payload bytes change, refresh their sizes and hashes while preserving package identity fields:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-package-builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./manifest.json</span></span></code></pre></div><h2 id="_3-build-and-inspect-the-archive" tabindex="-1">3. Build and inspect the archive <a class="header-anchor" href="#_3-build-and-inspect-the-archive" aria-label="Permalink to &quot;3. Build and inspect the archive&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-package-builder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./manifest.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./calculator.xpk</span></span></code></pre></div><p>The packager rejects files that differ from the manifest, creates a temporary archive, and checks it again through the separate TAR reader before renaming it to the output. This creates an <strong>unsigned package</strong>. No Xila command currently installs it.</p><p>The host builder reads payload files into memory and reads the completed TAR again for validation. <strong>Do not run this algorithm inside an MCU installer.</strong> The shared <code>xila-package-reader</code> also requires the entire archive as a slice.</p><p>An optional final argument to <code>pack</code> accepts a <strong>raw 64-byte Ed25519 signature</strong> supplied by a separate signing system. There is presently <strong>no official signer/trust provisioning workflow</strong>, so this guide deliberately does not treat supplying a signature as publishing a trusted release. See <a href="/reference/package-format.html#exact-provisional-signing-statement">provisional signed bytes</a> before experimenting.</p><h2 id="_4-run-the-repository-quality-checks" tabindex="-1">4. Run the repository quality checks <a class="header-anchor" href="#_4-run-the-repository-quality-checks" aria-label="Permalink to &quot;4. Run the repository quality checks&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clippy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage:lcov</span></span></code></pre></div><p><code>mise run coverage:lcov</code> requires the pinned <code>cargo-llvm-cov</code> and <code>llvm-tools-preview</code>; it writes an LCOV report for Codecov. The workspace has GitHub Actions checks, Dependabot and <strong>Git-only</strong> release-plz versioning. Crates are <strong>not published to crates.io</strong> (<code>publish = false</code>). GitHub releases may carry <code>xila-package</code> binaries for Linux/macOS/Windows once a corresponding release is created; the presence of a workflow does not guarantee one exists.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>To propose <strong>metadata</strong> for an externally hosted development package, read <a href="/how-to/submit-package.html">Submit a package declaration</a>. Do not imply the preview makes it installable or authenticated. For the complete current format and limits, read <a href="/reference/package-format.html">Package format</a>.</p>`,25)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
